/**
 * Sound effects, synthesised with Web Audio (D-23): no audio files, no network,
 * nothing generated by AI. Every sound is a few oscillator notes with an
 * envelope, so the whole "sound pack" is the table below.
 *
 * Browsers only allow audio after a user gesture: the AudioContext is created
 * lazily on the first play() (which always happens inside a tap handler or
 * shortly after one). Mute is remembered in localStorage when it's available.
 */

export type Sfx =
  | 'tap'
  | 'paint'
  | 'start'
  | 'tick'
  | 'warn'
  | 'go'
  | 'correct'
  | 'wrong'
  | 'timeout'
  | 'submit'
  | 'reveal'
  | 'milestone'
  | 'duelJoin'
  | 'win'
  | 'lose';

type Note = {
  /** Hz. */
  f: number;
  /** Start offset (s). */
  at: number;
  /** Duration (s). */
  d: number;
  type?: OscillatorType;
  /** Peak gain 0..1 (before master volume). */
  g?: number;
  /** Slide to this frequency over the note. */
  to?: number;
};

const C5 = 523.25;
const E5 = 659.25;
const G5 = 783.99;
const C6 = 1046.5;
const A4 = 440;

const SOUNDS: Record<Sfx, Note[]> = {
  tap: [{ f: 880, at: 0, d: 0.04, type: 'triangle', g: 0.25 }],
  paint: [{ f: 1200, at: 0, d: 0.025, type: 'sine', g: 0.12 }],
  start: [
    { f: 330, at: 0, d: 0.12, type: 'triangle', g: 0.35, to: 660 },
    { f: 660, at: 0.1, d: 0.12, type: 'triangle', g: 0.25 },
  ],
  tick: [{ f: 1000, at: 0, d: 0.03, type: 'square', g: 0.08 }],
  warn: [{ f: 1400, at: 0, d: 0.05, type: 'square', g: 0.12 }],
  go: [{ f: 880, at: 0, d: 0.18, type: 'triangle', g: 0.35 }],
  correct: [
    { f: C5, at: 0, d: 0.12, type: 'triangle', g: 0.35 },
    { f: E5, at: 0.09, d: 0.12, type: 'triangle', g: 0.35 },
    { f: G5, at: 0.18, d: 0.22, type: 'triangle', g: 0.35 },
  ],
  wrong: [
    { f: 300, at: 0, d: 0.16, type: 'sawtooth', g: 0.18, to: 220 },
    { f: 220, at: 0.15, d: 0.22, type: 'sawtooth', g: 0.16, to: 160 },
  ],
  timeout: [
    { f: A4, at: 0, d: 0.12, type: 'square', g: 0.12 },
    { f: A4, at: 0.18, d: 0.12, type: 'square', g: 0.12 },
    { f: 330, at: 0.36, d: 0.3, type: 'square', g: 0.12, to: 250 },
  ],
  submit: [
    { f: 600, at: 0, d: 0.08, type: 'triangle', g: 0.3, to: 900 },
    { f: 1200, at: 0.07, d: 0.1, type: 'sine', g: 0.2 },
  ],
  reveal: [{ f: 200, at: 0, d: 0.45, type: 'sine', g: 0.25, to: 800 }],
  milestone: [
    { f: C5, at: 0, d: 0.1, type: 'triangle', g: 0.3 },
    { f: E5, at: 0.08, d: 0.1, type: 'triangle', g: 0.3 },
    { f: G5, at: 0.16, d: 0.1, type: 'triangle', g: 0.3 },
    { f: C6, at: 0.24, d: 0.35, type: 'triangle', g: 0.35 },
  ],
  duelJoin: [
    { f: 660, at: 0, d: 0.1, type: 'square', g: 0.12 },
    { f: 990, at: 0.1, d: 0.16, type: 'square', g: 0.12 },
  ],
  win: [
    { f: G5, at: 0, d: 0.12, type: 'triangle', g: 0.3 },
    { f: C6, at: 0.12, d: 0.12, type: 'triangle', g: 0.3 },
    { f: G5, at: 0.24, d: 0.1, type: 'triangle', g: 0.3 },
    { f: C6, at: 0.34, d: 0.45, type: 'triangle', g: 0.35 },
  ],
  lose: [
    { f: G5, at: 0, d: 0.18, type: 'triangle', g: 0.25 },
    { f: E5, at: 0.18, d: 0.18, type: 'triangle', g: 0.25 },
    { f: C5, at: 0.36, d: 0.4, type: 'triangle', g: 0.25, to: 480 },
  ],
};

const STORAGE_KEY = 'blurprint:muted';
const MASTER_VOLUME = 0.5;
/** Minimum gap between two plays of the same sound (paint strokes fire fast). */
const MIN_GAP_MS: Partial<Record<Sfx, number>> = { paint: 45, tap: 30, tick: 200 };

const readMuted = (): boolean => {
  try {
    return globalThis.localStorage?.getItem(STORAGE_KEY) === '1';
  } catch {
    return false;
  }
};

let ctx: AudioContext | null = null;
let master: GainNode | null = null;
let muted = readMuted();
const lastPlayed = new Map<Sfx, number>();
const listeners = new Set<(muted: boolean) => void>();

/** The page's one AudioContext (shared with the music engine). Created lazily, inside a user gesture. */
export const ensureContext = (): AudioContext | null => {
  if (ctx) return ctx;
  const Ctor = globalThis.AudioContext;
  if (typeof Ctor !== 'function') return null;
  try {
    ctx = new Ctor();
    master = ctx.createGain();
    master.gain.value = MASTER_VOLUME;
    master.connect(ctx.destination);
  } catch {
    ctx = null;
  }
  return ctx;
};

export const sfx = {
  play(name: Sfx): void {
    if (muted) return;
    const now = performance.now();
    const gap = MIN_GAP_MS[name] ?? 0;
    if (gap && now - (lastPlayed.get(name) ?? -Infinity) < gap) return;
    lastPlayed.set(name, now);
    const ac = ensureContext();
    if (!ac || !master) return;
    if (ac.state === 'suspended') void ac.resume().catch(() => undefined);
    const t0 = ac.currentTime + 0.01;
    for (const n of SOUNDS[name]) {
      const osc = ac.createOscillator();
      const env = ac.createGain();
      osc.type = n.type ?? 'sine';
      osc.frequency.setValueAtTime(n.f, t0 + n.at);
      if (n.to) osc.frequency.exponentialRampToValueAtTime(n.to, t0 + n.at + n.d);
      const peak = n.g ?? 0.3;
      env.gain.setValueAtTime(0.0001, t0 + n.at);
      env.gain.exponentialRampToValueAtTime(peak, t0 + n.at + Math.min(0.012, n.d / 3));
      env.gain.exponentialRampToValueAtTime(0.0001, t0 + n.at + n.d);
      osc.connect(env).connect(master);
      osc.start(t0 + n.at);
      osc.stop(t0 + n.at + n.d + 0.02);
    }
  },
  isMuted: (): boolean => muted,
  setMuted(next: boolean): void {
    muted = next;
    try {
      globalThis.localStorage?.setItem(STORAGE_KEY, next ? '1' : '0');
    } catch {
      /* storage unavailable: keep it for this session only */
    }
    listeners.forEach((l) => l(next));
  },
  subscribe(fn: (muted: boolean) => void): () => void {
    listeners.add(fn);
    return () => listeners.delete(fn);
  },
};
